    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, IReadOnlyDictionary<string, string>?> Cache =
        new(StringComparer.OrdinalIgnoreCase);

    public static bool TryGetValue(string languageCode, string key, out string value)
    {
        if (Cache.GetOrAdd(languageCode, Build) is { } translations &&
            translations.TryGetValue(key, out var translation))
        {
            value = translation;
            return true;
        }

        value = string.Empty;
        return false;
    }

    private static IReadOnlyDictionary<string, string>? Build(string languageCode)
    {
        if (!Factories.TryGetValue(languageCode, out var factory))
            return null;

        // Drop dictionaries of languages that are no longer selected.
        foreach (var cached in Cache.Keys)
        {
            if (!cached.Equals(languageCode, StringComparison.OrdinalIgnoreCase))
                Cache.TryRemove(cached, out _);
        }

        var values = factory();
        if (values.Length != Keys.Length)
            throw new ArgumentException($"Translation count for {languageCode} does not match its keys.", nameof(languageCode));

        var dictionary = new Dictionary<string, string>(Keys.Length, StringComparer.OrdinalIgnoreCase);
        for (var index = 0; index < Keys.Length; index++)
            dictionary[Keys[index]] = values[index];
        return dictionary;
    }

